import { writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { Concept, Knowledge } from "../index/load.ts";

/** Folder order and headings for wiki/index.md. Unlisted folders follow, alphabetically. */
const SECTIONS: Array<[string, string]> = [
  ["profile", "Profile"],
  ["projects", "Projects"],
  ["people", "People"],
  ["tools", "Tools"],
  ["data-access", "Data access"],
  ["topics", "Topics"],
  ["sources", "Sources"],
];

export const INDEX_HEADER =
  "Every page in this wiki with a one-line summary, grouped by folder. Generated by `kb index`; do not edit by hand.";

function oneLine(c: Concept): string {
  const text = (c.meta.description ?? c.body.split(/\n\s*\n/)[0] ?? "")
    .replace(/\[\[([^\]|]+)\|([^\]]+)\]\]/g, "$2")
    .replace(/\[\[([^\]]+)\]\]/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
  const short = text.length > 140 ? `${text.slice(0, 139)}…` : text;
  const status = c.meta.status === "stable" ? "" : ` _(${c.meta.status})_`;
  return `- [[${c.id}|${c.meta.title}]]: ${short}${status}`;
}

/**
 * Karpathy's index.md: a catalog of every page, each with a link and a one-line summary,
 * organized by category. It is generated, so it can never drift from the pages themselves.
 */
export function renderIndex(k: Knowledge): string {
  const groups = new Map<string, Concept[]>();
  for (const c of k.concepts) {
    const folder = c.id.includes("/") ? (c.id.split("/")[0] ?? "") : "";
    groups.set(folder, [...(groups.get(folder) ?? []), c]);
  }
  const known = SECTIONS.map(([f]) => f);
  const order = [
    ...SECTIONS.filter(([f]) => groups.has(f)),
    ...[...groups.keys()]
      .filter((f) => !known.includes(f))
      .sort()
      .map((f): [string, string] => [f, f ? f[0]?.toUpperCase() + f.slice(1) : "Other"]),
  ];
  const parts = ["# Index", "", INDEX_HEADER, ""];
  for (const [folder, heading] of order) {
    const pages = groups.get(folder) ?? [];
    parts.push(`## ${heading} (${pages.length})`, "", ...pages.map(oneLine), "");
  }
  if (k.skills.length) {
    parts.push(
      `## Skills (${k.skills.length})`,
      "",
      ...k.skills.map((s) => `- \`${s.name}\`: ${s.description.replace(/\s+/g, " ").trim()}`),
      "",
    );
  }
  return parts.join("\n");
}

export async function writeIndex(root: string, k: Knowledge): Promise<{ pages: number }> {
  await writeFile(join(root, "wiki/index.md"), renderIndex(k));
  return { pages: k.concepts.length };
}
